import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry layernorm_affine(
    .param .u64 p_in,
    .param .u64 p_out,
    .param .u64 p_gamma,
    .param .u64 p_beta,
    .param .u32 p_norm,
    .param .u32 p_batch,
    .param .f32 p_eps
)
{
    .reg .pred   %p<6>;
    .reg .b32    %r<30>;
     .reg .b64    %rd<50>;
    .reg .f32    %f<40>;

    .shared .align 16 .f32 sh_sum[1024];
    .shared .align 16 .f32 sh_sumsq[1024];
    .shared .align 4  .f32 sh_mean;
    .shared .align 4  .f32 sh_invstd;

    // Load params
    ld.param.u64    %rd10, [p_in];
    ld.param.u64    %rd11, [p_out];
    ld.param.u64    %rd12, [p_gamma];
    ld.param.u64    %rd13, [p_beta];
    ld.param.u32    %r20,  [p_norm];
    ld.param.u32    %r21,  [p_batch];
    ld.param.f32    %f20,  [p_eps];

    // Thread/block info
    mov.u32         %r0, %tid.x;
    mov.u32         %r1, %ntid.x;
    mov.u32         %r2, %ctaid.x;

    // Compute base element index for this sample: base = blockIdx.x * norm_size
    mul.wide.u32    %rd20, %r2, %r20;      // u64 elements
    mul.wide.u32    %rd21, %r20, 4;        // bytes per sample
    mul.wide.u32    %rd22, %r2, %r20;      // elements again (redundant but clear)
    mul.lo.u64      %rd23, %rd22, 4;       // bytes per sample
    mul.wide.u32    %rd24, %r0, 4;         // tid * 4 (bytes) for shared addressing convenience

    // Base pointers for this sample in/out
    mul.wide.u32    %rd25, %r2, %r20;      // elements
    mul.lo.u64      %rd26, %rd25, 4;       // bytes
    add.s64         %rd30, %rd10, %rd26;   // base_in = in + bytes
    add.s64         %rd31, %rd11, %rd26;   // base_out = out + bytes

    // Prepare shared memory base addresses
     // Prepare shared memory base addresses
     mov.u64         %rd32, sh_sum;
     mov.u64         %rd33, sh_sumsq;
     mov.u64         %rd34, sh_mean;
     mov.u64         %rd35, sh_invstd;

    // Phase 1: compute partial sums over this sample
    mov.f32         %f0, 0f00000000;       // sum = 0.0
    mov.f32         %f1, 0f00000000;       // sumsq = 0.0

    mov.u32         %r3, %r0;              // idx = tid
L_loop_sum:
    setp.ge.u32     %p0, %r3, %r20;
    @%p0 bra        L_done_sum;

    // byte offset for element idx: off = idx * 4
    mul.wide.u32    %rd1, %r3, 4;
    add.s64         %rd2, %rd30, %rd1;     // addr = base_in + off
    ld.global.f32   %f2, [%rd2];

    // accumulate
    add.f32         %f0, %f0, %f2;
    mul.f32         %f3, %f2, %f2;
    add.f32         %f1, %f1, %f3;

    add.u32         %r3, %r3, %r1;         // idx += blockDim.x
    bra             L_loop_sum;

L_done_sum:
    // Write partials to shared memory
    add.s64         %rd4, %rd32, %rd24;    // &sh_sum[tid]
    st.shared.f32   [%rd4], %f0;
    add.s64         %rd5, %rd33, %rd24;    // &sh_sumsq[tid]
    st.shared.f32   [%rd5], %f1;

    bar.sync 0;

    // Tree reduction in shared memory
    // stride = 512
     setp.lt.u32 %p1, %r0, 512;
     @!%p1 bra   L_skip512;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 2048;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 2048;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip512:
     bar.sync 0;
    bar.sync 0;

    // stride = 256
     setp.lt.u32 %p1, %r0, 256;
     @!%p1 bra   L_skip256;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 1024;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 1024;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip256:
     bar.sync 0;

    // stride = 128
     setp.lt.u32 %p1, %r0, 128;
     @!%p1 bra   L_skip128;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 512;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 512;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip128:
     bar.sync 0;

    // stride = 64
     setp.lt.u32 %p1, %r0, 64;
     @!%p1 bra   L_skip64;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 256;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 256;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip64:
     bar.sync 0;

    // stride = 32
     setp.lt.u32 %p1, %r0, 32;
     @!%p1 bra   L_skip32;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 128;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 128;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip32:
     bar.sync 0;

    // stride = 16
     setp.lt.u32 %p1, %r0, 16;
     @!%p1 bra   L_skip16;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 64;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 64;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip16:
     bar.sync 0;

    // stride = 8
     setp.lt.u32 %p1, %r0, 8;
     @!%p1 bra   L_skip8;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 32;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 32;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip8:
     bar.sync 0;

    // stride = 4
     setp.lt.u32 %p1, %r0, 4;
     @!%p1 bra   L_skip4;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 16;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 16;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip4:
     bar.sync 0;

    // stride = 2
     setp.lt.u32 %p1, %r0, 2;
     @!%p1 bra   L_skip2;
         ld.shared.f32   %f4, [%rd4];
         add.s64         %rd6, %rd32, 8;
         add.s64         %rd7, %rd6, %rd24;
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         ld.shared.f32   %f6, [%rd5];
         add.s64         %rd8, %rd33, 8;
         add.s64         %rd9, %rd8, %rd24;
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
L_skip2:
     bar.sync 0;

     // stride = 1
     setp.lt.u32 %p1, %r0, 1;
     @!%p1 bra   L_skip1;
         // sum: sh_sum[0] += sh_sum[1]
         ld.shared.f32   %f4, [%rd4];            // sh_sum[tid]
         add.s64         %rd6, %rd32, 4;         // base + 4 bytes
         add.s64         %rd7, %rd6, %rd24;      // sh_sum[tid + 1]
         ld.shared.f32   %f5, [%rd7];
         add.f32         %f4, %f4, %f5;
         st.shared.f32   [%rd4], %f4;
         // sumsq: sh_sumsq[0] += sh_sumsq[1]
         ld.shared.f32   %f6, [%rd5];            // sh_sumsq[tid]
         add.s64         %rd8, %rd33, 4;         // base + 4 bytes
         add.s64         %rd9, %rd8, %rd24;      // sh_sumsq[tid + 1]
         ld.shared.f32   %f7, [%rd9];
         add.f32         %f6, %f6, %f7;
         st.shared.f32   [%rd5], %f6;
 L_skip1:
     bar.sync 0;
    // Compute mean and invstd by thread 0
    setp.eq.u32     %p2, %r0, 0;
     @!%p2 bra       L_after_stats;
         ld.shared.f32   %f8, [sh_sum];
         cvt.rn.f32.u32  %f10, %r20;        // N
         div.rn.f32      %f11, %f8, %f10;   // mean = sum / N
         st.shared.f32   [sh_mean], %f11;
L_after_stats:
    bar.sync 0;

    // Second pass: compute variance via sum of squared diffs
    // All threads: load mean and accumulate sum((x - mean)^2)
    ld.shared.f32   %f30, [sh_mean];
    mov.f32         %f1, 0f00000000;
    mov.u32         %r3, %r0;
L_loop_var:
    setp.ge.u32     %p4, %r3, %r20;
    @%p4 bra        L_done_var;
    mul.wide.u32    %rd1, %r3, 4;
    add.s64         %rd2, %rd30, %rd1;
    ld.global.f32   %f2, [%rd2];
    sub.f32         %f3, %f2, %f30;
    mul.f32         %f4, %f3, %f3;
    add.f32         %f1, %f1, %f4;
    add.u32         %r3, %r3, %r1;
    bra             L_loop_var;
L_done_var:
    // Write per-thread partials for squared diffs
    st.shared.f32   [%rd5], %f1;
    bar.sync 0;
    // Second reduction over sh_sumsq (and sh_sum, harmless) to get total squared diffs
    // stride = 512
    setp.lt.u32 %p1, %r0, 512;
    @!%p1 bra   L2_skip512;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 2048;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 2048;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip512:
    bar.sync 0;
    // stride = 256
    setp.lt.u32 %p1, %r0, 256;
    @!%p1 bra   L2_skip256;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 1024;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 1024;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip256:
    bar.sync 0;
    // stride = 128
    setp.lt.u32 %p1, %r0, 128;
    @!%p1 bra   L2_skip128;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 512;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 512;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip128:
    bar.sync 0;
    // stride = 64
    setp.lt.u32 %p1, %r0, 64;
    @!%p1 bra   L2_skip64;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 256;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 256;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip64:
    bar.sync 0;
    // stride = 32
    setp.lt.u32 %p1, %r0, 32;
    @!%p1 bra   L2_skip32;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 128;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 128;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip32:
    bar.sync 0;
    // stride = 16
    setp.lt.u32 %p1, %r0, 16;
    @!%p1 bra   L2_skip16;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 64;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 64;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip16:
    bar.sync 0;
    // stride = 8
    setp.lt.u32 %p1, %r0, 8;
    @!%p1 bra   L2_skip8;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 32;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 32;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip8:
    bar.sync 0;
    // stride = 4
    setp.lt.u32 %p1, %r0, 4;
    @!%p1 bra   L2_skip4;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 16;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 16;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip4:
    bar.sync 0;
    // stride = 2
    setp.lt.u32 %p1, %r0, 2;
    @!%p1 bra   L2_skip2;
        ld.shared.f32   %f4, [%rd4];
        add.s64         %rd6, %rd32, 8;
        add.s64         %rd7, %rd6, %rd24;
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        ld.shared.f32   %f6, [%rd5];
        add.s64         %rd8, %rd33, 8;
        add.s64         %rd9, %rd8, %rd24;
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip2:
    bar.sync 0;
    // stride = 1
    setp.lt.u32 %p1, %r0, 1;
    @!%p1 bra   L2_skip1;
        // sum: sh_sum[0] += sh_sum[1]
        ld.shared.f32   %f4, [%rd4];            // sh_sum[tid]
        add.s64         %rd6, %rd32, 4;         // base + 4 bytes
        add.s64         %rd7, %rd6, %rd24;      // sh_sum[tid + 1]
        ld.shared.f32   %f5, [%rd7];
        add.f32         %f4, %f4, %f5;
        st.shared.f32   [%rd4], %f4;
        // sumsq: sh_sumsq[0] += sh_sumsq[1]
        ld.shared.f32   %f6, [%rd5];            // sh_sumsq[tid]
        add.s64         %rd8, %rd33, 4;         // base + 4 bytes
        add.s64         %rd9, %rd8, %rd24;      // sh_sumsq[tid + 1]
        ld.shared.f32   %f7, [%rd9];
        add.f32         %f6, %f6, %f7;
        st.shared.f32   [%rd5], %f6;
L2_skip1:
    bar.sync 0;
    // Thread 0 computes invstd from sum of squared diffs
    setp.eq.u32     %p2, %r0, 0;
    @!%p2 bra       L_after_invstd;
        ld.shared.f32   %f18, [sh_sumsq];
        cvt.rn.f32.u32  %f10, %r20;        // N
        div.rn.f32      %f19, %f18, %f10;  // var
        add.f32         %f15, %f19, %f20;  // var + eps
        sqrt.rn.f32     %f16, %f15;        // sqrt(var + eps)
        rcp.rn.f32      %f17, %f16;        // invstd
        st.shared.f32   [sh_invstd], %f17;
L_after_invstd:
    bar.sync 0;
    // Load mean and invstd for all threads
    ld.shared.f32   %f30, [sh_mean];
    ld.shared.f32   %f31, [sh_invstd];
    // Phase 2: normalize and apply affine
    mov.u32         %r4, %r0;              // idx = tid
L_loop_norm:
    setp.ge.u32     %p3, %r4, %r20;
    @%p3 bra        L_done_norm;

    // offsets
     mul.wide.u32    %rd36, %r4, 4;             // idx*4
