def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_affine")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.normalized_shape = tuple(normalized_shape)
        numel = 1
        for d in self.normalized_shape:
            numel *= int(d)
        # Parameters match PyTorch LayerNorm defaults: weight=ones, bias=zeros, dtype=float32
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        assert tuple(x.shape[1:]) == self.normalized_shape, "Input shape must match normalized_shape"
        assert self.weight.shape == self.normalized_shape and self.bias.shape == self.normalized_shape
        assert self.weight.device == x.device and self.bias.device == x.device, "Parameters must be on same device as input"

        out = torch.empty_like(x)
        batch = x.shape[0]
        norm_size = 1
        for d in self.normalized_shape:
            norm_size *= int(d)

        module = _get_ptx_module()
        module.launch(
            "layernorm_affine",
            grid=(int(batch), 1, 1),
            block=(1024, 1, 1),
            arguments=[x, out, self.weight, self.bias, i32(norm_size), i32(batch), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
